<span class="line"><span style="color:#ABB2BF;">trainer </span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;"> paddle.optimizer.</span><span style="color:#61AFEF;">SGD</span><span style="color:#ABB2BF;">(</span><span style="color:#E06C75;font-style:italic;">learning_rate</span><span style="color:#56B6C2;">=</span><span style="color:#D19A66;">0.3</span><span style="color:#ABB2BF;">, </span><span style="color:#E06C75;font-style:italic;">parameters</span><span style="color:#56B6C2;">=</span><span style="color:#ABB2BF;">net.</span><span style="color:#61AFEF;">parameters</span><span style="color:#ABB2BF;">())</span></span>
